"""Assemble small browser modules into the DSH factory; no second React runtime."""
from pathlib import Path

root = Path(__file__).resolve().parents[1]
parts = ["kit", "canvas", "home", "assistant", "desk", "entry"]
body = "\n".join((root / "client" / f"{name}.js").read_text() for name in parts)
(root / "client.js").write_text(
    "// Generated by scripts/build_client.py. Edit client/*.js.\n"
    "window.__ModuleLoader__.load({id: 'dsh-hardwise', factory(require) {\n"
    + body + "\n}});\n"
)
